@pytest.mark.parametrize( "case", [ "unknown", "approval", "accounting_fail", "non_accounting", "known_no_actions", "external_transfer", ], ) def test_sql_issuance_matches_complete_permanent_python_contract( capture_context, enabled, case ): user, org = capture_context if case == "non_accounting": org.industry = "legal" org.save(update_fields=["industry"]) if case in { "approval", "accounting_fail", "known_no_actions", "non_accounting", "external_transfer", }: known_item = issue( capture_context, form( display_name="Explicit proposal specimen", business_owner="Responsible owner", business_purpose="Review declared workflow", human_approval="no", autonomy_level="3" if case != "known_no_actions" else "0", permissions=["write"] if case != "known_no_actions" else [NONE], capabilities={ "approval": ["communication"], "accounting_fail": ["financial_transaction", "record_modification"], "non_accounting": ["financial_transaction", "record_modification"], "known_no_actions": [NONE], "external_transfer": ["external_transfer"], }[case], connected_systems=["banking"], data_categories=["payroll", "tax_records"], ), ) snapshot = admit(capture_context, preview(capture_context)) revision = issue_proposals(capture_context, snapshot) assert revision.cards == build_review_proposals( snapshot_id=snapshot.id, capture_envelope=envelope(snapshot) ) assert issue_proposals(capture_context, snapshot).id == revision.id receipt = CaptureProposalAdmissionReceipt.objects.get(revision=revision) assert receipt.snapshot_id == snapshot.id assert receipt.input_sha256 == snapshot.input_sha256 assert receipt.result_sha256 == snapshot.result_sha256 assert receipt.revision_sha256 == revision.sha256 assert all( card["resolution_effect"] == "none" and card["resolution_verified"] is False for card in revision.cards ) generic = [ card for card in revision.cards if card["source"]["class"] != "accounting_fail" ] assert all("severity" not in card and "risk_score" not in card for card in generic) if case == "known_no_actions": normalized = next( record for record in snapshot.input_payload["inventory"] if record["id"] == str(known_item.id) ) assert normalized["permissions"] == [] assert normalized["capabilities"] == [] assert normalized["provenance"]["permissions"] == "Declared" assert normalized["provenance"]["capabilities"] == "Declared" assert normalized["human_approval"] is False assert normalized["autonomy_level"] == 0 assert not any( card["inventory_item_id"] == str(known_item.id) and card["source"]["identity"] == "approval" for card in revision.cards ) if case in {"accounting_fail", "external_transfer"}: > assert any( card["source"]["class"] == "accounting_fail" for card in revision.cards ) E assert False E + where False = any(<generator object test_sql_issuance_matches_complete_permanent_python_contract.<locals>.<genexpr> at 0x7b72ddedf920>)
